/**
 * R46 modeler/runtime compatibility matrix (generated by scripts/gen-compat.mjs) and the pre-deploy construct scan.
 * The scan warns; deploy-time rejection stays with the engine parse listeners and the package validator (R44).
 */
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import matrix from '../modeller/compatibility.json';
import type { ModelArtifact } from '../api/types';
import { Badge, DataTable, Notice, PageHeader, SearchBox, SelectField } from '../components/ui';

export interface CompatRow {
  notation: string;
  construct: string;
  modeller: string;
  engine: string;
  status: string;
  note: string;
  source: string;
  xml: string[];
}
const rows = matrix.rows as CompatRow[];
const BLOCKING = new Set(['REJECTED', 'UNSUPPORTED']);

export interface ScanFinding {
  artifact: string;
  construct: string;
  status: string;
  note: string;
  count: number;
}

export function scanModel(name: string, kind: string, content: string): ScanFinding[] {
  if (kind === 'FORM' || !content.trim()) return [];
  const doc = new DOMParser().parseFromString(content, 'application/xml');
  if (doc.getElementsByTagName('parsererror').length) return [];
  const out: ScanFinding[] = [];
  for (const r of rows.filter((x) => x.notation === kind && x.status !== 'SUPPORTED')) {
    let count = 0;
    for (const x of r.xml) count += doc.getElementsByTagNameNS('*', x).length;
    if (r.construct.startsWith('HitPolicy.')) {
      const policy = r.construct.split('.')[1];
      count = [...Array.from(doc.getElementsByTagNameNS('*', 'decisionTable'))].filter((d) => d.getAttribute('hitPolicy') === policy).length;
    }
    if (count > 0) out.push({ artifact: name, construct: r.construct, status: r.status, note: r.note, count });
  }
  return out;
}

export function scanArtifacts(artifacts: ModelArtifact[]): ScanFinding[] {
  return artifacts.flatMap((a) => scanModel(a.name, a.kind, a.content));
}

export const hasBlocking = (f: ScanFinding[]) => f.some((x) => BLOCKING.has(x.status));

export function ScanReport({ findings }: { findings: ScanFinding[] }) {
  const { t } = useTranslation();
  if (!findings.length) return <Notice tone="ok">{t('mod.compat.clean')}</Notice>;
  return (
    <>
      {hasBlocking(findings) && <Notice tone="bad">{t('mod.compat.blocking')}</Notice>}
      <DataTable
        caption={t('mod.compat.scan')}
        rows={findings.map((x, i) => ({ ...x, i }))}
        rowKey={(r) => String(r.i)}
        columns={[
          { key: 'artifact', header: t('modeller.artifact') },
          { key: 'construct', header: t('modeller.construct') },
          { key: 'status', header: t('admin.status'), render: (r) => <Badge value={r.status} tone={BLOCKING.has(r.status) ? 'bad' : 'warn'} /> },
          { key: 'count', header: t('batch.total'), render: (r) => String(r.count) },
          { key: 'note', header: t('admin.note') },
        ]}
      />
    </>
  );
}

export function CompatibilityMatrix() {
  const { t } = useTranslation();
  const [notation, setNotation] = useState('');
  const [status, setStatus] = useState('');
  const [q, setQ] = useState('');
  const shown = useMemo(() => rows.filter((r) => (!notation || r.notation === notation) && (!status || r.status === status) && r.construct.toLowerCase().includes(q.toLowerCase())), [notation, status, q]);
  return (
    <>
      <PageHeader title={t('mod.compat.title')} description={t('mod.compat.desc')} />
      <div className="filters">
        <SearchBox label={t('common.search')} value={q} onChange={setQ} />
        <SelectField label={t('fld.notation')} value={notation} onChange={setNotation} placeholder={t('common.all')} options={['BPMN', 'DMN', 'CMMN'].map((v) => ({ value: v, label: v }))} />
        <SelectField label={t('admin.status')} value={status} onChange={setStatus} placeholder={t('common.all')} options={['SUPPORTED', 'SUPPORTED_WITH_RULES', 'PORTED', 'NOT_EXECUTABLE', 'REJECTED', 'UNSUPPORTED'].map((v) => ({ value: v, label: t(`opt.${v}`) }))} />
      </div>
      <DataTable
        caption={t('mod.compat.title')}
        captionHidden
        rows={shown}
        rowKey={(r) => `${r.notation}:${r.construct}`}
        columns={[
          { key: 'notation', header: t('fld.notation') },
          { key: 'construct', header: t('modeller.construct') },
          { key: 'modeller', header: t('mod.compat.modeller'), render: (r) => t(`opt.${r.modeller}`) },
          { key: 'engine', header: t('mod.compat.engine'), render: (r) => t(`opt.${r.engine}`) },
          { key: 'status', header: t('admin.status'), render: (r) => <Badge value={t(`opt.${r.status}`)} tone={BLOCKING.has(r.status) ? 'bad' : r.status === 'SUPPORTED' ? 'ok' : 'warn'} /> },
          { key: 'note', header: t('admin.note') },
          { key: 'source', header: t('fld.source') },
        ]}
      />
    </>
  );
}
